--
-- Name: update_device_trust(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_device_trust() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    WITH device_stats AS (
        SELECT 
            device_id,
            COUNT(*) as total,
            COUNT(CASE WHEN status = 'verified' THEN 1 END) as trusted,
            COUNT(CASE WHEN status = 'flagged' THEN 1 END) as flagged
        FROM reports
        WHERE device_id = NEW.device_id
        GROUP BY device_id
    )
    UPDATE devices d
    SET 
        total_reports = ds.total,
        trusted_reports = ds.trusted,
        flagged_reports = ds.flagged,
        device_trust_score = 
            (ds.trusted::FLOAT / NULLIF(ds.total, 0) * 70) +
            LEAST(ds.total, 50) * 0.5 -
            LEAST(ds.flagged * 5, 30),
        last_seen_at = NOW()
    FROM device_stats ds
    WHERE d.device_id = ds.device_id;
    
    RETURN NEW;
END;
$$;


